import copy

from django.core.exceptions import ValidationError
from django.db import models
from jsonschema import validate as jsonschema_validate, ValidationError as JsonSchemaValidationError

from osf.models.base import BaseModel, ObjectIDMixin
from osf.utils.datetime_aware_jsonfield import DateTimeAwareJSONField

# Fields generated by the CEDAR server on instance creation — frontend never sends them
CEDAR_SERVER_GENERATED_FIELDS = frozenset({
    '@id',
    'pav:createdOn',
    'pav:createdBy',
    'pav:lastUpdatedOn',
    'oslc:modifiedBy',
    'schema:isBasedOn',
    'schema:name',
    'schema:description',
})


def _allow_empty_optional_multiple_choice(schema):
    # cedar-embeddable-editor sends [] for a multiple choice field with nothing selected,
    # so minItems only applies when the field is required
    if not isinstance(schema, dict):
        return
    for child in schema.get('properties', {}).values():
        if not isinstance(child, dict):
            continue
        items = child.get('items')
        if isinstance(items, dict):
            constraints = items.get('_valueConstraints', {})
            if constraints.get('multipleChoice') and not constraints.get('requiredValue'):
                child.pop('minItems', None)
            _allow_empty_optional_multiple_choice(items)
        else:
            _allow_empty_optional_multiple_choice(child)


def _filter_context(metadata, schema):
    if not isinstance(metadata, dict) or not isinstance(schema, dict):
        return
    properties = schema.get('properties', {})
    context = metadata.get('@context')
    context_schema = properties.get('@context', {})
    defined_context = context_schema.get('properties')
    # elements with attribute-value fields allow extra @context keys, keep them there
    if isinstance(context, dict) and isinstance(defined_context, dict) and context_schema.get('additionalProperties') is False:
        filtered_context = {
            k: v for k, v in context.items()
            if k in defined_context
        }
        if filtered_context:
            metadata['@context'] = filtered_context
        else:
            metadata.pop('@context', None)
    for key, value in metadata.items():
        child_schema = properties.get(key)
        if key == '@context' or not isinstance(child_schema, dict):
            continue
        if isinstance(value, list):
            for item in value:
                _filter_context(item, child_schema.get('items'))
        else:
            _filter_context(value, child_schema)


class CedarMetadataTemplate(ObjectIDMixin, BaseModel):
    schema_name = models.CharField(max_length=255, default=None)
    cedar_id = models.CharField(max_length=255, default=None)
    template = DateTimeAwareJSONField(default=dict)
    active = models.BooleanField(default=True)
    template_version = models.PositiveIntegerField()
    should_index_for_search = models.BooleanField(default=False)
    is_for_collections = models.BooleanField(default=False)

    class Meta:
        unique_together = ('cedar_id', 'template_version')

    def __unicode__(self):
        return f'(name=[{self.schema_name}], version=[{self.template_version}], id=[{self.cedar_id}])'

    def get_semantic_iri(self):
        return self.cedar_id

    def is_active(self):
        return self.active


class CedarMetadataRecord(ObjectIDMixin, BaseModel):

    guid = models.ForeignKey('Guid', on_delete=models.CASCADE, related_name='cedar_metadata_records')
    template = models.ForeignKey('CedarMetadataTemplate', on_delete=models.CASCADE)
    metadata = DateTimeAwareJSONField(default=dict)
    is_published = models.BooleanField(default=False)

    class Meta:
        unique_together = ('guid', 'template')

    def __unicode__(self):
        return f'(guid=[{self.guid._id}], template=[{self.template._id}])'

    def get_template_semantic_iri(self):
        return self.template.get_semantic_iri()

    def get_template_name(self):
        return self.template.schema_name

    def get_template_version(self):
        return self.template.template_version

    def clean(self):
        if self.is_published:
            schema = copy.deepcopy(self.template.template)
            if 'required' in schema:
                schema['required'] = [
                    f for f in schema['required']
                    if f not in CEDAR_SERVER_GENERATED_FIELDS
                ]
            _allow_empty_optional_multiple_choice(schema)
            # Workaround for CEDAR components injecting extra keys (e.g. static fields) into
            # @context, also in nested elements; strip them down to the schema keys before saving.
            _filter_context(self.metadata, schema)
            try:
                jsonschema_validate(self.metadata, schema)
            except JsonSchemaValidationError as e:
                raise ValidationError(
                    f'CEDAR metadata does not validate against template "{self.template.schema_name}": {e.message}'
                )

    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        self.guid.referent.update_search()
